function relocatedTestPaths(filePath, contents) {
  const ownerPath = path.posix.normalize(filePath.replaceAll("\\", "/"));
  const modules = [...contents.matchAll(/#\[cfg\(test\)\]\s*#\[path = "([^"]+)"\]\s*mod \w+;/gu)];
  const includes = ownerPath.includes("/tests/")
    ? [...contents.matchAll(/^include!\("([^"]+)"\);$/gmu)]
    : [];
  return [...modules, ...includes]
    .map((match) => path.posix.join(path.posix.dirname(ownerPath), match[1]))
    .filter((testPath) => RELOCATED_TEST_FILES.has(testPath));
}

async function promotedSource(filePath) {
  const contents = await fs.readFile(path.join(repoRoot, filePath), "utf8");
  const tests = await Promise.all(relocatedTestPaths(filePath, contents)
    .map((testPath) => fs.readFile(path.join(repoRoot, testPath), "utf8")));
  return [contents, ...tests].join("\n");
}

async function promotedFiles() {
  const files = await Promise.all(
    [...PROMOTED_FILES, GEMINI_CONTENT_JSON_CALLER_FILE, GEMINI_CONTENT_JSON_ADAPTER_FILE, GEMINI_CONTENT_JSON_MOJO_FILE].map(async (filePath) => [
      filePath,
      await promotedSource(filePath),
    ]),
  );
  for (const filePath of REMOVED_ORACLE_FILES) {
    try {
      files.push([filePath, await fs.readFile(path.join(repoRoot, filePath), "utf8")]);
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    }
  }
  files.push(...await Promise.all(
    [...REQUIRED_DEFAULT_FEATURES.keys()].map(async (filePath) => [
      filePath,
      await fs.readFile(path.join(repoRoot, filePath), "utf8"),
    ]),
  ));
  files.push(["crates/prodex-cli/Cargo.toml", await fs.readFile(path.join(repoRoot, "crates/prodex-cli/Cargo.toml"), "utf8")]);
  files.push([RUNTIME_PROXY_CARGO_FILE, await fs.readFile(path.join(repoRoot, RUNTIME_PROXY_CARGO_FILE), "utf8")]);
  files.push([RUNTIME_TUNING_CARGO_FILE, await fs.readFile(path.join(repoRoot, RUNTIME_TUNING_CARGO_FILE), "utf8")]);
  return files;
}

